def restore_and_generate():
    headers = [
        "كود المنتج",
        "اسم المنتج التجاري",
        "اسم المنتج بالمتجر",
        "وصف المنتج",
        "أقل سعر مستهلك (ج.م)",
        "أعلى سعر مستهلك (ج.م)",
        "احطياطي مخزون",
        "سعر الجمله",
        "رابط الصورة المحلي"
    ]
    
    rows = [headers]
    valid_exts = ('.jpg', '.png', '.jpeg', '.mp4')
    
    files = os.listdir(img_dir)
    
    for filename in files:
        if filename.lower().endswith(valid_exts):
            base_code, _ = os.path.splitext(filename)
            file_url = f"file:///C:/Users/FOX/Desktop/فرح%20لستور/new_images/{filename}"
            
            if base_code in restored_data:
                d = restored_data[base_code]
            elif base_code in ai_data:
                d = ai_data[base_code]
            else:
                d = ["منتج جديد", "منتج جديد", "وصف عام", "100", "200", "10", "80"]
                
            row = [base_code] + d + [file_url]
            rows.append(row)
            
    with open(target_file, 'w', encoding='utf-8-sig', newline='') as f:
        writer = csv.writer(f, quoting=csv.QUOTE_MINIMAL)
        writer.writerows(rows)
        
    print(f"Successfully restored and generated {len(rows)-1} products.")

if __name__ == "__main__":
    restore_and_generate()
